namespace ghidra.app.plugin.core.analysis;

using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * Background task to artificially kick off Auto analysis by
 * calling anything that analyzes bytes.
 */
public class OneShotAnalysisCommand : BackgroundCommand<Program>, AutoAnalysisManagerListener {
	private Analyzer analyzer;
	private AddressSetView set;
	private MessageLog log;

	private Program lastProgram;

	public OneShotAnalysisCommand(Analyzer analyzer, AddressSetView set, MessageLog log) : base(analyzer.getName() + " - One Time", true, true, false)
    {
		this.analyzer = analyzer;
		this.set = set;
		this.log = log;
	}

	/* @Override */
	public bool applyTo(Program program, TaskMonitor monitor) {
		this.lastProgram = program;
		try {
			monitor.setMessage(analyzer.getName());
			return analyzer.added(program, set, monitor, log);
		}
		catch (CancelledException e) {
			return false;
		}
	}

	/* @Override */
	public void analysisEnded(AutoAnalysisManager manager, bool isCancelled) {
		if (lastProgram != null) {
			analyzer.analysisEnded(lastProgram);
		}
	}

	/* @Override */
	public string getStatusMsg() {
		string statusMessage = log.getStatus();

		if (statusMessage.length() > 0) {
			return statusMessage;
		}

		return null;
	}

}
